import json
d=json.load(open('/workspace/products/research/apify-store-csv-search.json'))
items=d.get('data',{}).get('items',[])
out=[]
for i in items:
  s=i.get('stats') or {}
  p=i.get('currentPricingInfo') or {}
  out.append({'name':i.get('username','')+'/'+i.get('name',''),'title':i.get('title'),'users_total':s.get('totalUsers'),'users_30d':s.get('totalUsers30Days') or s.get('monthlyUsers'),'runs':s.get('totalRuns'),'pricing_model':p.get('pricingModel'),'price':p.get('pricePerUnitUsd') or p.get('pricingPerEvent'),'desc':(i.get('description') or '')[:160]})
out.sort(key=lambda x:-(x['users_30d'] or 0))
res={'source':'https://api.apify.com/v2/store?search=csv&limit=30','fetched_task':'TASK-179365860212','total':d.get('data',{}).get('total'),'items':out,'note':'Store stats are public listing data, untrusted; users are not revenue.'}
open('/workspace/products/research/apify-csv-demand-summary.json','w').write(json.dumps(res,indent=1))
for o in out[:15]: print(o['name'],o['users_30d'],o['users_total'],o['pricing_model'],json.dumps(o['price'])[:120],'|',o['desc'][:90])
